        {typeof window === 'undefined' ? (
          <PreloadChunks moduleIds={opts.modules} />
        ) : null}
        <Lazy {...props} />
      </>
    ) : (
      <BailoutToCSR reason="next/dynamic">
        <Lazy {...props} />
      </BailoutToCSR>
    )

    return <Wrap {...wrapProps}>{children}</Wrap>
  }

  LoadableComponent.displayName = 'LoadableComponent'

  return LoadableComponent
}

